    );
    seed.evidence.push({ id: 'EV1', conversation_id: 'CONV1', case_id: 'CS001', type: 'image', path: '/files/demo/parcel_a.jpg', source: 'customer', created_at: at(-1, 9, 1) });
    seed.case_events.push(
