      { id: 'CE4', case_id: 'CS001', type: 'reply_sent', actor: 'CS_A', payload: { message_id: 'R1', approved_by: 'CS_A', shipment_snapshot: { A: 'delivered', B: 'in_transit' } }, created_at: at(-1, 9, 4) },
